// Hybrid retriever with parallel BM25 + vector search
export class HybridRetriever {
  async search(query: string, options?: RetrievalOptions): Promise<ExtendedSearchResult[]> {
    const mode = options?.mode ?? this.defaultMode;
    const queryTerms = this.tokenizeQuery(query);

    switch (mode) {
      case 'keyword': return await this.keywordSearch(query, queryTerms, options);
      case 'semantic': return await this.semanticSearch(query, queryTerms, options);
      case 'hybrid': default: return await this.hybridSearch(query, queryTerms, options);
    }
  }

  private async hybridSearch(query: string, queryTerms: string[], options: RetrievalOptions) {
    const [keywordResults, vectorResults] = await Promise.all([
      this.keywordSearchRaw(query, options),
      this.semanticSearchRaw(query, options),
    ]);

    const rrf = getRRFFusion(options.rrf);
    return rrf.fuse(keywordResults, vectorResults);
  }
}

// Retrieval types (Story 7-4)
export type SearchMode = 'keyword' | 'semantic' | 'hybrid';

export interface ExtendedSearchResult extends SearchResult {
  highlightedText?: string;
  matchedTerms: string[];
  rank: number;
  source: 'bm25' | 'vector' | 'rrf';
}

export interface RetrievalOptions {
  mode?: SearchMode;
  limit?: number;
  similarity?: number;
  includeVectors?: boolean;
  properties?: string[];
  bm25?: BM25Config;
  rrf?: RRFConfig;
}

// RAG State Management (Zustand)
interface RAGStoreState {
  // Search state (Story 7-4)
  searchQuery: string;
  searchResults: ExtendedSearchResult[];
  searchMode: SearchMode;

  // Actions
  performSearch: (query: string, mode?: SearchMode) => Promise<ExtendedSearchResult[]>;
  setSearchMode: (mode: SearchMode) => void;
  clearSearchResults: () => void;
}

// TanStack AI chat endpoint
export const loader: LoaderFunction = async ({ request }) => {
  const { messages } = await request.json();

  const stream = chat({
    adapter: openaiText('gpt-4o'),
    messages,
    stream: true,
  });

  return new Response(streamToSSE(stream));
};

architecture_patterns.pattern:
Use tools to inject retrieved context:
1. Define ragTool with toolDefinition
2. Server implementation performs hybrid retrieval
3. Tool returns chunks with citations
4. LLM generates response using context
5. Stream response with inline citations [1], [2], [3]

Example:
const ragTool = toolDefinition({
  name: 'search_knowledge',
  description: 'Search knowledge base for relevant context',
  inputSchema: z.object({ query: z.string() }),
}).server(async ({ query }) => {
  const results = await hybridRetriever.search(query);
  return { chunks: results.map(r => r.document) };
});

Build context window with structured format:
```
[Source 1]
Title: {title}
Content: {chunk content}

[Source 2]
Title: {title}
Content: {chunk content}

Question: {user query}
```

Priority placement:
- Most relevant chunks at beginning
- Secondary context at end
- Avoid burying important info in middle

example.code:
import { toolDefinition } from '@tanstack/ai';
import { z } from 'zod';

export const ragToolDef = toolDefinition({
  name: 'search_knowledge',
  description: 'Search knowledge base for relevant context',
  inputSchema: z.object({
    query: z.string().describe('User question to search for'),
  }),
  outputSchema: z.object({
    chunks: z.array(z.object({
      id: z.string(),
      title: z.string(),
      content: z.string(),
      position: z.number(),
    })),
  }),
});

export const ragTool = ragToolDef.server(async ({ query }) => {
  const retriever = await getHybridRetriever();
  const results = await retriever.search(query, { limit: 10 });
  return {
    chunks: results.map(r => ({
      id: r.document.id,
      title: r.document.title,
      content: r.document.content,
      position: r.document.position,
    })),
  };
});

function buildContext(chunks: DocumentChunk[]): string {
  return chunks.map((chunk, index) => `
[Source ${index + 1}]
Title: ${chunk.title || 'Untitled'}
Content: ${chunk.content}
---
  `).join('\n').trim();
}

function buildPrompt(query: string, context: string): string {
  return `Answer the following question using the provided sources. Cite your answers using [source_number] notation.

${context}

Question: ${query}

Instructions:
- Use information from the provided sources
- Cite each claim with [source_number]
- If sources don't contain the answer, say so
- Do not make up information`;
}

// Add to RAGStore
sendRAGMessage: async (query: string) => {
  set({ loading: true, error: null });

  try {
    // Step 1: Retrieve context
    const retriever = await getHybridRetriever();
    const results = await retriever.search(query, { limit: 10 });

    // Step 2: Build citations map
    const citations = new Map<string, Citation>();
    results.forEach((result, index) => {
      citations.set(String(index + 1), {
        id: index + 1,
        sourceId: result.document.id,
        title: result.document.title,
        passage: result.highlightedText || result.document.content,
      });
    });

    // Step 3: Generate response with RAG tool
    const response = await chat({
      adapter: openaiText('gpt-4o'),
      messages: [
        ...get().chatMessages,
        { role: 'user', content: query }
      ],
      tools: [ragTool],
    });

    // Step 4: Update state
    set({
      chatMessages: [
        ...get().chatMessages,
        { role: 'user', content: query },
        { role: 'assistant', content: response, citations: Array.from(citations.values()) }
      ],
      citations,
      loading: false,
    });
  } catch (error) {
    set({ error: (error as Error).message, loading: false });
  }
},

showCitation: (citationId: string) => {
  const citation = get().citations.get(citationId);
  if (citation) {
    set({ activeCitation: citation });
  }
},

closeCitationPanel: () => {
  set({ activeCitation: null });
},
